class Boundary extends React.Component {
  state = { failed: false };

  static getDerivedStateFromError() {
    return { failed: true };
  }

  render() {
    if (this.state.failed) return <p>Erro</p>;
    return this.props.children;
  }
}

class Item extends React.PureComponent {
